import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int e = sc.nextInt();
            int s = sc.nextInt();
            int l = sc.nextInt();

            int minPos = Math.min(e, Math.min(s, l));
            int maxPos = Math.max(e, Math.max(s, l));

            int totalDistance = 2 * (maxPos - minPos);

            System.out.println(totalDistance);
        }
    }
}
